const KBEAUTY_TROUBLESHOOTER_META = {"id":"troubleshooter","title":"Is this working — or hurting me?","intro":"Three quick, non-diagnostic tools to read what your skin is telling you. Educational only — these help you understand a reaction; they are not medical advice. If a reaction is severe, painful, spreading, or lasts beyond a few weeks, see a doctor or dermatologist.","disclaimer":"Structure-function & educational information only. Not a diagnosis and not a substitute for professional medical care."};
const KBEAUTY_PURGE = {"id":"purge","title":"Purging vs. Breakout","subtitle":"One of the most-asked K-beauty questions. Answer 4 quick questions to read your skin's reaction.","primer":"\"Purging\" can happen when a cell-turnover active (retinoids, AHA/BHA, some vitamin C) speeds up exfoliation, so microcomedones that were already forming surface faster and sooner. A \"reaction\" (irritation or clogging) is when a product simply doesn't agree with your skin. The clearest tells are timing, location, and whether it settles.","purgeActives":["retinol","bakuchiol","aha","bha","pha","vitaminc","azelaic"],"questions":[{"id":"newactive","q":"Did this start after introducing a cell-turnover active (a retinoid, AHA/BHA/PHA, or vitamin C)?","options":[{"label":"Yes — I added one of those","score":{"purge":2}},{"label":"No — it started with a richer cream, oil, balm or SPF","score":{"react":2}},{"label":"Not sure / nothing changed","score":{"react":1}}]},{"id":"timing","q":"How long after starting the product did the bumps appear?","options":[{"label":"Within the first ~2–6 weeks","score":{"purge":2}},{"label":"Right away (1–3 days)","score":{"react":2}},{"label":"After 6–8 weeks or longer of steady use","score":{"react":2}}]},{"id":"where","q":"Where are the new bumps showing up?","options":[{"label":"In my usual breakout zones, where I tend to get them anyway","score":{"purge":2}},{"label":"In new areas I don't normally break out","score":{"react":2}},{"label":"Everywhere a product touched / where I applied it","score":{"react":1}}]},{"id":"feel","q":"What does the skin feel like alongside the bumps?","options":[{"label":"Small surfacing bumps that come and clear faster than usual","score":{"purge":2}},{"label":"Stinging, burning, tightness, redness, flaking or itch","score":{"react":2,"barrier":2}},{"label":"Tiny uniform itchy bumps on forehead/hairline/chest/back","score":{"fungal":3}}]}],"outcomes":{"purge":{"verdict":"Likely purging","emoji":"🔄","headline":"This pattern looks like purging — give it time.","body":"Your reaction lines up with purging: it began after a turnover active, within roughly 2–6 weeks, in your usual breakout zones, and clears faster than a normal blemish. Purging is temporary and typically settles within about 4–8 weeks (up to ~12 for stronger retinoids) as your skin adjusts.","do":["Keep the active, but pull back the frequency — e.g. 2–3×/week instead of daily — and build up slowly.","Buffer it: apply over a light moisturizer, or 'sandwich' between hydrating layers, to ease irritation.","Support the barrier with niacinamide, panthenol, ceramides and a gentle hydrator.","Wear SPF 50+ every morning — actives make skin more sun-sensitive.","Resist the urge to add more actives at once; one change at a time."],"dont":["Don't quit on day 3 and assume it 'broke you out' — purging needs a few weeks to resolve.","Don't pick or over-exfoliate the surfacing bumps.","Don't stack a second strong active on top while you adjust."],"ingredientIds":["niacinamide","panthenol","ceramide","centella","hyaluronic"],"shopSeed":"redness","reassess":"If it's still worsening after ~8–12 weeks, treat it as a reaction (below) and re-evaluate the product."},"react":{"verdict":"Likely a reaction (not purging)","emoji":"🚫","headline":"This pattern looks more like a reaction than purging.","body":"Purging happens where you already break out and only with turnover actives. New bumps in new areas, an immediate response, congestion from a rich cream/oil/SPF, or a flare after 6–8 weeks of steady use all point to the product not agreeing with your skin — not purging.","do":["Pause the suspected product and simplify to a gentle cleanser, a basic moisturizer and SPF.","Reintroduce one product at a time so you can identify the culprit (patch-test on the jaw first).","If bumps are tiny, uniform and itchy on the forehead/hairline/chest/back, run the Fungal-Acne check below.","Look for heavy occlusives, comedogenic oils or fragrance in the product — decode the label below."],"dont":["Don't push through hoping it'll 'purge out' — non-purging congestion usually doesn't.","Don't add actives onto already-reacting skin."],"ingredientIds":["centella","panthenol","ceramide","niacinamide"],"shopSeed":"redness","reassess":"Persistent, painful or spreading breakouts deserve a professional opinion."}}};
const KBEAUTY_BARRIER = {"id":"barrier","title":"Barrier-Damage Symptom Check","subtitle":"A surging topic. Tick what you're experiencing — we'll gauge how stressed your barrier looks and map a recovery protocol.","primer":"Your skin barrier is the outer layer of cells and lipids that holds water in and keeps irritants out. Over-exfoliation, too many actives at once, harsh cleansing, or weather can compromise it — leaving skin tight, stingy and reactive. The fix is almost always less, not more.","symptoms":[{"id":"sting","label":"Products that used to feel fine now sting or burn","weight":2},{"id":"tight","label":"Persistent tightness, even after moisturizing","weight":1},{"id":"red","label":"New redness, flushing or blotchiness","weight":1},{"id":"flake","label":"Flaking, rough patches or peeling","weight":1},{"id":"shiny","label":"Skin looks tight-shiny or feels 'raw'","weight":2},{"id":"dehydrated","label":"Dehydrated yet sometimes oily (over-stripped)","weight":1},{"id":"reactive","label":"Suddenly reacting to products I tolerated before","weight":2},{"id":"overdid","label":"I've been using strong actives often, or layering several","weight":1}],"levels":[{"id":"ok","min":0,"max":2,"verdict":"Barrier looks fairly comfortable","emoji":"🟢","headline":"Your barrier seems mostly okay — keep it simple.","body":"Few of the classic stress signs are present. Maintain a calm, hydration-forward routine and introduce any new active slowly, one at a time.","protocol":[{"step":1,"title":"Maintain a gentle base","detail":"Low-pH cleanser, a hydrating toner/essence, and a barrier-supporting moisturizer.","ingredientIds":["hyaluronic","panthenol","ceramide"]},{"step":2,"title":"Add actives mindfully","detail":"One new active at a time, a few nights a week, with SPF every morning.","ingredientIds":["niacinamide"]}],"pauseActives":false,"shopSeed":"dryness"},{"id":"stressed","min":3,"max":5,"verdict":"Barrier looks stressed","emoji":"🟡","headline":"Several signs point to a stressed barrier — ease off and rebuild.","body":"Your skin is showing real signs of strain. The goal for the next 1–2 weeks is to calm, hydrate and rebuild — and to pause anything that exfoliates or sensitizes until comfort returns.","protocol":[{"step":1,"title":"Pause all actives","detail":"Stop retinoids, AHA/BHA/PHA, vitamin C and scrubs for now. Give skin a reset.","ingredientIds":[]},{"step":2,"title":"Cleanse gently","detail":"Once at night with a creamy, low-pH cleanser; lukewarm water only. Skip the AM cleanse if skin feels raw — rinse with water.","ingredientIds":[]},{"step":3,"title":"Flood with soothing hydration","detail":"A fragrance-free centella or panthenol toner/essence pressed onto damp skin.","ingredientIds":["centella","panthenol","betaglucan","madecassoside"]},{"step":4,"title":"Rebuild the lipids","detail":"A ceramide-rich moisturizer to restore the barrier's 'mortar' and lock moisture in.","ingredientIds":["ceramide","squalane","hyaluronic"]},{"step":5,"title":"Protect by day","detail":"Gentle SPF 50+ every morning — UV slows recovery. A mineral SPF can feel calmer on raw skin.","ingredientIds":[]}],"pauseActives":true,"reintroduce":"Once skin feels comfortable again (often ~1–2 weeks), reintroduce ONE active at a low frequency and build slowly.","shopSeed":"redness"},{"id":"compromised","min":6,"max":99,"verdict":"Barrier looks compromised","emoji":"🔴","headline":"Strong signs of a compromised barrier — strip back to recovery basics.","body":"Many stress signs are present. Pare your routine right down to a 3-step recovery core, pause every active, and prioritize comfort. Most barriers rebound within a couple of weeks of consistent, gentle care.","protocol":[{"step":1,"title":"Pause every active immediately","detail":"No retinoids, acids, vitamin C, scrubs, or strong fragrance until skin is calm and comfortable.","ingredientIds":[]},{"step":2,"title":"Minimalist gentle cleanse","detail":"Night only, creamy low-pH cleanser or even just lukewarm water if cleansing stings.","ingredientIds":[]},{"step":3,"title":"Soothe & hydrate","detail":"Fragrance-free centella/panthenol/beta-glucan layer on damp skin to calm and draw in water.","ingredientIds":["centella","madecassoside","panthenol","betaglucan"]},{"step":4,"title":"Seal & repair","detail":"A rich ceramide cream; for very dry, raw skin, a thin occlusive 'slug' overnight can help hold moisture.","ingredientIds":["ceramide","squalane"]},{"step":5,"title":"Daytime protection","detail":"Gentle SPF 50+ daily. If even SPF stings, a mineral formula may be more comfortable.","ingredientIds":[]}],"pauseActives":true,"reintroduce":"Hold the recovery routine until skin is consistently calm. Reintroduce a single active only after full comfort returns — slowly. If symptoms are severe, oozing, painful or persistent, please see a dermatologist.","shopSeed":"redness"}],"rescueBrands":[{"id":"roundlab","note":"Birch Juice / Mugwort lines — gentle daily barrier care"},{"id":"pyunkangyul","note":"Minimalist barrier toner & moisture cream"},{"id":"drjart","note":"Ceramidin — ceramide barrier range"},{"id":"purito","note":"Fragrance-free, vegan centella"},{"id":"torriden","note":"DIVE-IN low-molecular hyaluronic hydration"}]};
const KBEAUTY_FUNGAL = {"id":"fungal","title":"Fungal-Acne (Malassezia) Aware Mode","subtitle":"A deep-enthusiast rabbit hole. Flip the decoder into Fungal-Acne mode and it flags ingredients commonly reported to feed malassezia yeast.","primer":"\"Fungal acne\" (the common nickname for malassezia folliculitis) isn't true acne — it's tiny, uniform, often itchy bumps on the forehead, hairline, chest, back and shoulders, driven by a yeast that lives on everyone's skin. That yeast feeds on certain fatty acids and esters, so many enthusiasts avoid those ingredients. This mode is an educational screen, not a diagnosis — see a doctor for itchy, persistent bumps; some cases need antifungal treatment.","tellTale":["Tiny, same-size bumps rather than varied pimples","Clustered on forehead, hairline, jaw, chest, back or shoulders","Often itchy","Flares with heat, sweat, occlusion, or after rich oils/creams","Doesn't respond to normal acne products"],"explainerByFamily":{"fatty-acid":"Fatty acids in roughly the C11–C24 range (e.g. lauric, myristic, palmitic, stearic, oleic) are a common food source for malassezia.","fatty-ester":"Esters of those fatty acids (often -ate endings like isopropyl myristate, glyceryl stearate, ascorbyl palmitate) are frequently avoided on fungal-safe routines.","fatty-alcohol":"Fatty alcohols (cetyl, stearyl, etc.) are a debated maybe — many tolerate them, but cautious routines limit them.","plant-oil-butter":"Most plant oils and butters contain feeding fatty acids; common exceptions reported as lower-risk are squalane, MCT/caprylic-capric triglyceride and mineral oil.","polysorbate":"Polysorbates and some PEG/sorbitan esters are flagged as possible feeders by cautious routines.","ferment":"Some fermented ingredients (e.g. galactomyces) are commonly avoided in strict fungal-safe routines."},"flagInci":{"fatty-acid":["stearic acid"],"fatty-ester":["isopropyl myristate","isopropyl palmitate","glyceryl stearate","glyceryl stearate se","ascorbyl palmitate","ascorbyl tetraisopalmitate","retinyl palmitate","tocopheryl acetate","peg-7 glyceryl cocoate","sorbitan oleate","peg-80 sorbitan laurate","polyglyceryl-10 laurate"],"fatty-alcohol":["cetyl alcohol","stearyl alcohol"],"plant-oil-butter":["butyrospermum parkii (shea) butter","simmondsia chinensis (jojoba) seed oil","helianthus annuus (sunflower) seed oil","cocos nucifera (coconut) oil","prunus amygdalus dulcis (sweet almond) oil","argania spinosa kernel oil","rosa canina fruit oil","olea europaea (olive) fruit oil","persea gratissima (avocado) oil","theobroma cacao (cocoa) seed butter","camellia japonica seed oil","hippophae rhamnoides oil"],"polysorbate":["polysorbate 20","polysorbate 80","peg-40 hydrogenated castor oil"],"ferment":["galactomyces ferment filtrate"]},"flagPatterns":[{"family":"fatty-ester","regex":"(myristate|palmitate|stearate|oleate|laurate|linoleate|isostearate|cocoate)\\b"},{"family":"fatty-acid","regex":"\\b(lauric|myristic|palmitic|stearic|oleic|linoleic|undecylenic)\\s+acid\\b"},{"family":"fatty-alcohol","regex":"\\b(lauryl|myristyl|cetyl|cetearyl|stearyl|oleyl|behenyl)\\s+alcohol\\b"},{"family":"polysorbate","regex":"\\b(polysorbate|sorbitan)\\b"},{"family":"plant-oil-butter","regex":"\\b(seed oil|fruit oil|kernel oil|nut oil|\\) oil|seed butter|\\) butter)\\b"}],"safeKeys":["squalane","caprylic/capric triglyceride","mineral oil","petrolatum","dimethicone"],"safeNote":"Commonly reported as lower-risk on fungal-safe routines.","safeIngredientIds":["niacinamide","centella","hyaluronic","panthenol"],"safeHelpers":"Many people lean on lightweight, ester-light actives such as niacinamide, centella, hyaluronic acid and (as a leave-on for some) sulfur, salicylic acid, zinc pyrithione or ketoconazole — but treatment choices should be guided by a professional.","decoderEmptyAllSafe":"No common malassezia-feeding ingredients flagged in this list. This is an educational screen only, not a guarantee — formulas and individual tolerance vary.","decoderModeLabel":"🍄 Fungal-acne mode","decoderModeHint":"Flags esters, fatty acids/alcohols, most oils & butters, polysorbates and certain ferments that are commonly avoided on fungal-safe routines.","shopSeed":"redness"};
